"""Real workbook upload/extraction/preview/download regression coverage."""
from pathlib import Path
import json

import pytest

from lan_codex_share.document_extract import extract_document
from lan_codex_share.document_store import DocumentStore, document_input
from tests.test_archive_preview import xlsx_bytes
from tests.test_document_store import payload
from tests.test_document_web import document_web
from tests.test_lan_web import request, mutation_headers


def workbook(extension):
    if extension == '.xls':
        # Generated by xlwt 1.3.0; xlwt is not a runtime/test dependency.
        return Path(__file__).with_name('fixtures').joinpath('upload-workbook.xls').read_bytes()
    return xlsx_bytes('<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'
                      '<row r="1"><c r="A1" t="inlineStr"><is><t>角色权限</t></is></c>'
                      '<c r="B1"><f>1+1</f><v>2</v></c><c r="C1"><f>2+2</f></c></row>'
                      '<row r="201"><c r="AY201" t="inlineStr"><is><t>远处数据</t></is></c></row>'
                      '</sheetData></worksheet>')


@pytest.mark.parametrize('extension', ['.xlsx', '.xls'])
def test_excel_extraction_all_sheets_beyond_preview_caps(tmp_path, extension):
    path = tmp_path / ('权限' + extension)
    path.write_bytes(workbook(extension))
    result = extract_document(path)
    assert '角色权限' in result['text']
    assert 'AY201\t远处数据' in result['text']
    assert '[工作表：' in result['text']
    assert '不执行公式' in result['warning']
    if extension == '.xlsx':
        assert 'B1\t2' in result['text']
        assert 'C1\t公式结果未缓存' in result['text']
        assert '[工作表：空表]' in result['text']
    else:
        assert '[工作表：说明]\nA1\t第二张工作表' in result['text']
        assert 'B2\tTRUE' in result['text']
        assert 'D2\t2026-11-23' in result['text']


@pytest.mark.parametrize('extension', ['.xlsx', '.xls'])
def test_excel_upload_model_input_preview_restart_and_download(document_web, extension):
    app, server, service, _ = document_web
    raw = workbook(extension)
    body = json.dumps({'documents': [payload('权限' + extension.upper(), raw)]})
    status, _, response = request(server, 'POST', '/api/messages', body, mutation_headers(server, app.csrf_token))
    assert status == 202, response
    pending = service.snapshot()['pending'][0]
    document = pending['documents'][0]
    document_id = document['id']
    endpoint = f'/api/documents/{document_id}?session_id=thread-lan'
    status, headers, contents = request(server, 'GET', endpoint)
    assert status == 200 and contents == raw
    assert dict(headers)['Content-Disposition'].startswith('attachment;')
    preview = f'/api/documents/{document_id}/preview?session_id=thread-lan'
    status, _, contents = request(server, 'GET', preview)
    result = json.loads(contents)
    assert status == 200 and result['kind'] == 'spreadsheet', contents
    assert result['truncated'] and result['sheet'] == 0
    assert len(result['rows']) <= 200
    assert all(len(row) <= 50 for row in result['rows'])
    assert request(server, 'GET', preview + '&sheet=1')[0] == 200
    for sheet in ['-1', '2', 'oops']:
        assert request(server, 'GET', preview + '&sheet=' + sheet)[0] == 400
    assert request(server, 'GET', preview.replace('thread-lan', 'wrong-session'))[0] == 400
    restarted = DocumentStore(app.document_store.directory)
    _, record = restarted.resolve(document_id, 'thread-lan')
    model = document_input(record)['text']
    assert '远处数据' in model and '用户上传的文档材料' in model
    assert 'text' not in document
    with pytest.raises(FileNotFoundError):
        restarted.resolve(document_id, 'another')
    assert service.cancel_queued(pending['id'], 'local')
    assert request(server, 'GET', endpoint)[0] == 404


@pytest.mark.parametrize('extension', ['.xlsx', '.xls'])
def test_corrupt_excel_rolls_back_entire_upload(tmp_path, extension):
    store = DocumentStore(tmp_path)
    with pytest.raises(ValueError):
        store.save_many([payload('valid.txt', b'first'), payload('broken' + extension, b'not Excel')])
    assert not list(tmp_path.glob('*.txt')) and not list(tmp_path.glob('*' + extension))


def test_large_excel_upload_keeps_original_and_explicit_excerpt(tmp_path):
    path = tmp_path / 'large.xlsx'
    path.write_bytes(xlsx_bytes('<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'
                               '<row r="201"><c r="AY201" t="inlineStr"><is><t>' + '文' * 100001 +
                               '</t></is></c></row></sheetData></worksheet>'))
    result = extract_document(path)
    assert len(result['text']) <= 20_000 and result['text_truncated']
    assert result['sheet_names'] == ['方案', '空表']
    assert '完整原文件' in result['warning'] and '无需拆表' in result['warning']
    store = DocumentStore(tmp_path / 'uploads')
    docs = store.save_many([payload('大表.xlsx', path.read_bytes()) for _ in range(5)])
    store.bind('s', 'm', '', docs)
    for doc in docs:
        material = json.loads(document_input(doc)['text'].split('\n', 1)[1])
        assert material['excerpt_truncated']
        assert Path(material['local_file']).read_bytes() == path.read_bytes()
    public = store.metadata('s', 'm')['documents']
    assert all('local_path' not in doc and 'text' not in doc for doc in public)
    restored = DocumentStore(store.directory).resolve(docs[0]['id'], 's')[1]
    assert restored['local_path'] == docs[0]['local_path']


def test_excel_batch_not_rejected_by_plain_document_text_ceiling(tmp_path, monkeypatch):
    # Same bounded extractor output for a configured 11-workbook batch.
    monkeypatch.setattr('lan_codex_share.document_store.extract_isolated',
                        lambda _: {'text': 'x' * 20000, 'warning': '内容节选', 'text_truncated': True})
    store = DocumentStore(tmp_path, max_documents=20)
    docs = store.save_many([payload(f'{i}.xlsx', workbook('.xlsx')) for i in range(11)])
    assert len(docs) == 11 and all(Path(doc['local_path']).is_file() for doc in docs)


@pytest.mark.parametrize('extra', [[('xl/vbaProject.bin', b'macro')], [('xl/../evil.xml', b'bad')]])
def test_unsafe_xlsx_upload_rejected(tmp_path, extra):
    path = tmp_path / 'bad.xlsx'
    path.write_bytes(xlsx_bytes(extra=extra))
    with pytest.raises(ValueError):
        extract_document(path)
